 1  type EventCleanup = () => void
 2  
 3  type MMGISAPI = {
 4      request: (name: string, params?: unknown) => Promise<unknown>
 5      on: (event: string, handler: (payload?: unknown) => void) => EventCleanup
 6      emit: (event: string, payload?: unknown) => void
 7      provide?: (name: string, handler: (...args: unknown[]) => unknown) => EventCleanup
 8      hasHandler?: (name: string) => boolean
 9  }
10  
11  declare global {
12      interface Window {
13          mmgisAPI?: MMGISAPI
14      }
15  }
16  
17  export const mmgisRequest = async <T = unknown>(name: string, params?: unknown): Promise<T | null> => {
18      if (window.mmgisAPI?.request) {
19          return (await window.mmgisAPI.request(name, params)) as T
20      }
21      return null
22  }
23  
24  export const mmgisOn = (event: string, handler: (payload?: unknown) => void): EventCleanup => {
25      if (!window.mmgisAPI?.on) return () => {}
26      return window.mmgisAPI.on(event, handler)
27  }
28  
29  export const mmgisEmit = (event: string, payload?: unknown): void => {
30      window.mmgisAPI?.emit?.(event, payload)
31  }
32  
33  export const mmgisProvide = (name: string, handler: (...args: unknown[]) => unknown): EventCleanup => {
34      if (!window.mmgisAPI?.provide) return () => {}
35      return window.mmgisAPI.provide(name, handler)
36  }
37  
38  export const mmgisHasHandler = (name: string): boolean => {
39      return window.mmgisAPI?.hasHandler?.(name) === true
40  }

