 1  const WebSocket = require("isomorphic-ws");
 2  const logger = require("./logger");
 3  
 4  const websocket = {
 5    wss: null,
 6    init: function (server) {
 7      logger("info", "Trying to init websocket...", "websocket", null, "");
 8  
 9      if (!server === null) {
10        logger(
11          "websocket_error",
12          "server parameter not defined.",
13          "error",
14          null,
15          ""
16        );
17        return null;
18      }
19  
20      logger(
21        "info",
22        "Server is valid so still trying to init websocket...",
23        "websocket",
24        null,
25        ""
26      );
27  
28      const wss = new WebSocket.Server({ noServer: true });
29      websocket.wss = wss;
30  
31      // Heartbeat: proxies and load balancers silently drop idle connections,
32      // so periodically ping every client and terminate the ones that stopped
33      // answering. Browsers answer pings automatically.
34      const pingIntervalMs =
35        parseInt(process.env.WEBSOCKET_PING_INTERVAL_MS, 10) || 30000;
36      const heartbeatInterval = setInterval(() => {
37        wss.clients.forEach((client) => {
38          if (client.isAlive === false) {
39            client.terminate();
40            return;
41          }
42          client.isAlive = false;
43          client.ping();
44        });
45      }, pingIntervalMs);
46  
47      // Broadcast to all clients
48      wss.broadcast = function broadcast(data, isBinary) {
49        wss.clients.forEach((client) => {
50          if (client.readyState === WebSocket.OPEN && data !== undefined) {
51            client.send(data, { binary: isBinary });
52          }
53        });
54      };
55  
56      wss.on("connection", (ws) => {
57        ws.isAlive = true;
58        ws.on("pong", () => {
59          ws.isAlive = true;
60        });
61        ws.on("message", (message) => {
62          wss.broadcast(message);
63        });
64      });
65  
66      server.on("upgrade", function upgrade(request, socket, head) {
67        const pathname = request.url;
68        try {
69          if (
70            pathname ===
71            (process.env.WEBSOCKET_ROOT_PATH || process.env.ROOT_PATH || "") + "/"
72          ) {
73            wss.handleUpgrade(request, socket, head, function done(ws) {
74              wss.emit("connection", ws, request);
75            });
76          } else {
77            socket.destroy();
78          }
79        } catch (err) {
80          socket.destroy();
81        }
82      });
83  
84      wss.on("close", () => {
85        logger("info", "Websocket disconnected...", "websocket", null, "");
86        clearInterval(heartbeatInterval);
87        websocket.wss = null;
88      });
89    },
90  };
91  
92  module.exports = { websocket };

